 static byte[] Zip(Dictionary<string,byte[]> entries){using(var memory=new MemoryStream()){using(var zip=new ZipArchive(memory,ZipArchiveMode.Create,true))foreach(var item in entries){var entry=zip.CreateEntry(item.Key);using(var stream=entry.Open())stream.Write(item.Value,0,item.Value.Length);}return memory.ToArray();}}
