static partial class NativeTests {
 static ProcessIdentity Ticket(int id){return new ProcessIdentity{Id=id,ParentId=0,SessionId=1,Started=100,Name="ChatGPT",Path="C:\\official\\ChatGPT.exe",Owner="test-user"};}
 static void ProcessTests(){
  Test("running_without_close_authorization_preserves_config",()=>{var f=new Fixture();f.Processes.Entries.Add(Ticket(1));var r=f.Init();Assert(r.state=="failed"&&f.Processes.Requested==0&&!Directory.Exists(f.P.BackupRoot),"unapproved close or mutation");});
  Test("authorized_natural_exit_continues",()=>{var f=new Fixture();f.Processes.Entries.Add(Ticket(2));f.Processes.Natural=true;f.O.AllowClose=true;f.O.ApprovedProcesses=new[]{"2:100"};var r=f.Init();Assert(r.state=="complete"&&f.Processes.Forced==0,"natural exit stopped");});
  Test("authorized_residual_exit_continues",()=>{var f=new Fixture();f.Processes.Entries.Add(Ticket(3));f.O.AllowClose=true;f.O.ApprovedProcesses=new[]{"3:100"};var r=f.Init();Assert(r.state=="complete"&&f.Processes.Forced==1,"residual close");});
  Test("new_instance_before_close_is_not_authorized",()=>{var f=new Fixture();var t=Ticket(4);t.Started=200;f.Processes.Entries.Add(t);f.O.AllowClose=true;f.O.ApprovedProcesses=new[]{"4:100"};var r=f.Init();Assert(r.state=="failed"&&f.Processes.Requested==0&&!Directory.Exists(f.P.BackupRoot),"new instance closed");});
  Test("restart_while_waiting_stops_before_mutation",()=>{var f=new Fixture();f.Processes.Entries.Add(Ticket(5));f.Processes.OnWait=p=>{p.Entries.Clear();p.Entries.Add(Ticket(6));};f.O.AllowClose=true;f.O.ApprovedProcesses=new[]{"5:100"};var r=f.Init();Assert(r.state=="failed"&&f.Processes.Forced==0&&!Directory.Exists(f.P.BackupRoot),"restart not stopped");});
  Test("close_permission_failure_preserves_config",()=>{var f=new Fixture();f.Processes.Denied=true;var r=f.Init();Assert(r.state=="failed"&&f.Registry.Writes==0&&!Directory.Exists(f.P.BackupRoot),"permission fail continued");});
  Test("close_timeout_stops_before_backup",()=>{var f=new Fixture();f.Processes.Entries.Add(Ticket(7));f.Processes.KeepAfterForce=true;f.O.AllowClose=true;f.O.ApprovedProcesses=new[]{"7:100"};var r=f.Init();Assert(r.state=="failed"&&!Directory.Exists(f.P.BackupRoot),"timeout continued");});
  Test("gone_during_authorized_request_is_skipped",()=>{var f=new Fixture();var p=Ticket(8);f.Processes.Entries.Add(p);f.Processes.Natural=true;NativeProcessWorkflow.EnsureStopped(f.P,f.Desktop.App,f.Processes,true,new[]{p.Key},delegate{});Assert(f.Processes.Entries.Count==0&&f.Processes.Forced==0,"gone PID");});
 }
 static void CuaTests(){
  Test("cua_runtime_id_matches_independent_sha_contract",()=>{var f=new Fixture();var combined=new StringBuilder();foreach(var name in new[]{"manifest.json","bin/node.exe","bin/node_repl.exe"})combined.Append(name).Append('\0').Append(NativeCua.Hash(Path.Combine(f.Desktop.App.Source,name.Replace('/',Path.DirectorySeparatorChar)))).Append('\0');Assert(NativeCua.RuntimeId(f.Desktop.App.Source)==NativeCua.HashBytes(Encoding.UTF8.GetBytes(combined.ToString())).Substring(0,16),"runtime ID");NativeCua.ValidateAlgorithm(KnownAlgorithm);var golden=Path.Combine(f.P.Documents,"golden");NativeData.Write(Path.Combine(golden,"manifest.json"),"manifest-test");NativeData.Write(Path.Combine(golden,"bin","node.exe"),"node-test");NativeData.Write(Path.Combine(golden,"bin","node_repl.exe"),"repl-test");Assert(NativeCua.RuntimeId(golden)=="b5b98a31756046fb","independent golden runtime identity");});
  Test("cua_check_is_readonly_and_repair_is_idempotent",()=>{var f=new Fixture();var cua=new NativeCua(f.P,f.S);var check=cua.Run(false,Path.Combine(f.P.Documents,"reports"));Assert(!check.Passed&&!Directory.Exists(f.P.RuntimeRoot),"check mutated");var repaired=cua.Run(true,Path.Combine(f.P.Documents,"reports"));Assert(repaired.Passed&&repaired.Changed,"repair");var again=cua.Run(true,Path.Combine(f.P.Documents,"reports-2"));Assert(again.Passed&&!again.Changed,"repeat copy");});
  Test("cua_corruption_preserves_original_backup",()=>{var f=new Fixture();NativeData.Write(Path.Combine(f.Target,"old-file"),"original corrupted data");var r=new NativeCua(f.P,f.S).Run(true,Path.Combine(f.P.Documents,"reports"));Assert(r.Passed&&File.ReadAllText(Path.Combine(r.Backup,"old-file"))=="original corrupted data","old tree backup");Assert(NativeTree.Read(f.Desktop.App.Source).Same(f.Target,null),"full tree equality");});
  Test("cua_copy_failure_restores_original_tree",()=>{var f=new Fixture();NativeData.Write(Path.Combine(f.Target,"old-file"),"original");var cua=new NativeCua(f.P,f.S);cua.Copy=(source,target)=>{NativeData.Write(Path.Combine(target,"partial"),"partial");throw new IOException("controlled copy failure");};Throws(()=>cua.Run(true,Path.Combine(f.P.Documents,"reports")),"原状态已恢复");Assert(File.ReadAllText(Path.Combine(f.Target,"old-file"))=="original"&&!File.Exists(Path.Combine(f.Target,"partial")),"original not restored");});
  Test("cua_unknown_algorithm_stops_without_runtime_write",()=>{var f=new Fixture();f.Desktop.App.StartupCode="unknown";Throws(()=>new NativeCua(f.P,f.S).Run(true,Path.Combine(f.P.Documents,"reports")),"标识算法");Assert(!Directory.Exists(f.P.RuntimeRoot),"unknown modified");});
  Test("cua_app_version_change_stops_without_copy",()=>{var f=new Fixture();var app=f.Desktop.App;f.Desktop.Next=n=>n==1?app:new OfficialDesktop{FullName="changed",Install=app.Install,Source=app.Source,StartupCode=KnownAlgorithm};Throws(()=>new NativeCua(f.P,f.S).Run(true,Path.Combine(f.P.Documents,"reports")),"发生变化");Assert(!Directory.Exists(f.P.RuntimeRoot),"version change copy");});
  Test("cua_source_change_during_copy_restores_original",()=>{var f=new Fixture();var originalTarget=f.Target;NativeData.Write(Path.Combine(originalTarget,"old-file"),"original");var cua=new NativeCua(f.P,f.S);cua.Copy=(tree,target)=>{tree.CopyTo(target);NativeData.Write(Path.Combine(tree.Root,"manifest.json"),"changed source");};Throws(()=>cua.Run(true,Path.Combine(f.P.Documents,"reports")),"原状态已恢复");Assert(File.ReadAllText(Path.Combine(originalTarget,"old-file"))=="original","source-change rollback");});
  Test("cua_running_process_stops_repair",()=>{var f=new Fixture();f.Processes.Entries.Add(Ticket(9));Throws(()=>new NativeCua(f.P,f.S).Run(true,Path.Combine(f.P.Documents,"reports")),"仍在运行");Assert(!Directory.Exists(f.P.RuntimeRoot),"running copy");});
  Test("cua_empty_directories_and_extra_files_are_checked",()=>{var f=new Fixture();var tree=NativeTree.Read(f.Desktop.App.Source);tree.CopyTo(f.Target);Assert(tree.Same(f.Target,null),"copied empty dir");Directory.Delete(Path.Combine(f.Target,"empty"));Assert(!tree.Same(f.Target,null),"missing empty dir accepted");Directory.CreateDirectory(Path.Combine(f.Target,"empty"));NativeData.Write(Path.Combine(f.Target,"extra"),"extra");Assert(!tree.Same(f.Target,null),"extra accepted");});
  Test("cua_managed_browser_patch_is_preserved_and_reapplied",()=>{var f=new Fixture();var tree=NativeTree.Read(f.Desktop.App.Source);tree.CopyTo(f.Target);string id=Path.GetFileName(f.Target),relative=Path.Combine("tools","cua-repl.mjs");var original=File.ReadAllBytes(Path.Combine(f.Desktop.App.Source,relative));var patched=NativeBrowserPatch.Generate(original,"http://127.0.0.1:3067");var state=Path.Combine(f.P.LocalData,"CodexInitKit","Desktop","BrowserConnection");NativeData.WriteBytes(Path.Combine(state,id+"-"+NativeCua.HashBytes(original)+".bin"),original);NativeData.Write(Path.Combine(state,id+".json"),NativeData.Json.Serialize(new{schema=1,runtimeId=id,source=f.Desktop.App.Source,target=f.Target,originalHash=NativeCua.HashBytes(original),patchedHash=NativeCua.HashBytes(patched),packageFullName=f.Desktop.App.FullName,proxy="http://127.0.0.1:3067"}));NativeData.WriteBytes(Path.Combine(f.Target,relative),patched);var first=new NativeCua(f.P,f.S).Run(false,Path.Combine(f.P.Documents,"report"));Assert(first.Passed,"managed patch flagged corrupt");File.Delete(Path.Combine(f.Target,"bin","node_repl.exe"));var repaired=new NativeCua(f.P,f.S).Run(true,Path.Combine(f.P.Documents,"report"));Assert(repaired.Passed&&File.ReadAllBytes(Path.Combine(f.Target,relative)).SequenceEqual(patched),"managed patch lost");File.AppendAllText(Path.Combine(f.Target,relative),"third party");Throws(()=>new NativeCua(f.P,f.S).Run(true,Path.Combine(f.P.Documents,"report")),"未识别修改");});
  Test("cua_failure_marks_partial_after_base_success",()=>{var f=new Fixture();f.Desktop.App.StartupCode="unknown";var r=f.Init();Assert(r.state=="partial"&&r.ExitCode==3&&File.Exists(f.P.Agents),"CUA failure state");});
 }
}

static partial class NativeTests {
 static NativeUpdateManifest Manifest(){return new NativeUpdateManifest{schema_version=1,repository=NativeUpdater.Repository,component="native-init-cli",version="2.3.1.2",url="https://github.com/BerryFuwawa/codex-init-kit/releases/download/v2.3.1.2/CodexInitKit.Cli.exe",sha256=NativeCua.Hash(UpdateFixture)};}
 static void UpdateTests(){
  Test("local_download_access_failure_stops_without_mirror_retries",()=>{var f=new Fixture();int attempts=0;var transfer=new GitHubTransfer(new GitHubNetworkOptions(),0,"127.0.0.1",null);transfer.ReadFile=(url,path)=>{attempts++;throw new UnauthorizedAccessException("controlled local access failure");};transfer.ProbeFile=(url,original,cancel)=>{throw new Exception("must not probe mirrors after local access failure");};Throws(()=>transfer.Download("https://github.com/BerryFuwawa/codex-init-kit/releases/download/test/CodexInitKit.Cli.exe",Path.Combine(f.P.Documents,"download.exe"),delegate{}),"本地下载文件");Assert(attempts==1,"repeated local blocked action");});

  Test("native_update_manifest_rejects_legacy_component_and_wrong_repository",()=>{var m=Manifest();m.component="init";Throws(()=>NativeUpdater.Parse(NativeData.Json.Serialize(m)),"组件");m=Manifest();m.repository="other/repo";Throws(()=>NativeUpdater.Parse(NativeData.Json.Serialize(m)),"组件");});
  Test("native_update_manifest_rejects_wrong_download_address_and_hash",()=>{var m=Manifest();m.url="https://evil.example/CodexInitKit.Cli.exe";Throws(()=>NativeUpdater.Parse(NativeData.Json.Serialize(m)),"地址");m=Manifest();m.sha256="bad";Throws(()=>NativeUpdater.Parse(NativeData.Json.Serialize(m)),"清单");});
  Test("native_update_check_is_readonly",()=>{var f=new Fixture();f.Downloads.Manifest=NativeData.Json.Serialize(Manifest());var result=new NativeUpdater(f.Downloads).Check();Assert(result.version=="2.3.1.2"&&f.Downloads.FileCalls==0,"check downloaded");});
  Test("native_update_prepare_and_apply_preserve_backup",()=>{var f=new Fixture();var target=Path.Combine(f.P.Documents,"CodexInitKit.Cli.exe");File.Copy(Cli,target);var original=File.ReadAllBytes(target);var plan=new NativeUpdater(f.Downloads).Prepare(Manifest(),target,NativeData.Version);int restarted=0;var backup=NativeUpdater.Apply(plan,p=>{Assert(p==target,"restart target");restarted++;});Assert(restarted==1&&File.ReadAllBytes(target).SequenceEqual(File.ReadAllBytes(UpdateFixture)),"new bytes");Assert(File.ReadAllBytes(backup).SequenceEqual(original),"update backup");Assert(!File.Exists(plan.stage)&&!File.Exists(plan.stage+".json"),"stage cleanup");});
  Test("native_update_restart_failure_restores_original",()=>{var f=new Fixture();var target=Path.Combine(f.P.Documents,"CodexInitKit.Cli.exe");File.Copy(Cli,target);var old=File.ReadAllBytes(target);var plan=new NativeUpdater(f.Downloads).Prepare(Manifest(),target,NativeData.Version);Throws(()=>NativeUpdater.Apply(plan,p=>{throw new IOException("controlled restart failure");}),"原程序已保留或恢复");Assert(File.ReadAllBytes(target).SequenceEqual(old),"restart rollback");});
  Test("native_update_bad_download_does_not_replace_original",()=>{var f=new Fixture();f.Downloads.BadHash=true;var target=Path.Combine(f.P.Documents,"CodexInitKit.Cli.exe");File.Copy(Cli,target);var old=File.ReadAllBytes(target);Throws(()=>new NativeUpdater(f.Downloads).Prepare(Manifest(),target,NativeData.Version),"SHA-256");Assert(File.ReadAllBytes(target).SequenceEqual(old)&&Directory.GetFiles(f.P.Documents,"CodexInitKit.Cli.next-*").Length==0,"bad download effects");});
  Test("native_update_changed_target_is_not_overwritten",()=>{var f=new Fixture();var target=Path.Combine(f.P.Documents,"CodexInitKit.Cli.exe");File.Copy(Cli,target);var plan=new NativeUpdater(f.Downloads).Prepare(Manifest(),target,NativeData.Version);File.WriteAllText(target,"user changed target");Throws(()=>NativeUpdater.Apply(plan,delegate{}),"目标已变化");Assert(File.ReadAllText(target)=="user changed target","changed target lost");});
  Test("native_update_changed_stage_is_rejected",()=>{var f=new Fixture();var target=Path.Combine(f.P.Documents,"CodexInitKit.Cli.exe");File.Copy(Cli,target);var old=File.ReadAllBytes(target);var plan=new NativeUpdater(f.Downloads).Prepare(Manifest(),target,NativeData.Version);File.AppendAllText(plan.stage,"changed");Throws(()=>NativeUpdater.Apply(plan,delegate{}),"SHA-256");Assert(File.ReadAllBytes(target).SequenceEqual(old),"changed stage installed");});
  Test("native_update_current_version_does_not_download",()=>{var f=new Fixture();var m=Manifest();m.version=NativeData.Version;Throws(()=>new NativeUpdater(f.Downloads).Prepare(m,Cli,NativeData.Version),"最新版本");Assert(f.Downloads.FileCalls==0,"downloaded same version");});
 }
 static void RuntimeTests(){
  Test("real_generated_rollback_entry_preserves_arguments",()=>{var f=new Fixture();f.P.Self=UpdateFixture;f.P.EntryPrefix="--native ";var session=NativeSession.Create(f.P,f.Registry,false);var marker=Path.Combine(f.P.Home,"rollback-arguments.txt");var info=new ProcessStartInfo(Environment.GetEnvironmentVariable("ComSpec"),"/d /c "+NativeData.Quoted(Path.Combine(session.root,"Rollback.cmd"))){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};info.EnvironmentVariables["CODEX_NATIVE_TEST_ARGS"]=marker;using(var process=Process.Start(info)){var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();Assert(process.WaitForExit(10000),"rollback entry timeout");Assert(process.ExitCode==0,"rollback entry: "+output.Result+error.Result);}var args=File.ReadAllLines(marker,Encoding.UTF8);Assert(args.Length==5&&args[0]=="--native"&&args[1]=="rollback"&&args[2]=="--session"&&args[4]=="--confirm","rollback argument boundaries");Assert(Path.GetFullPath(args[3])==Path.GetFullPath(session.root),"rollback session path");});

  Test("real_native_update_worker_waits_and_replaces_only_isolated_cli",()=>{var f=new Fixture();var old=Path.Combine(Path.GetDirectoryName(AssemblyPath()),"old-cli-fixture.exe");var target=Path.Combine(f.P.Documents,"CodexInitKit.Cli.exe");File.Copy(old,target);var original=File.ReadAllBytes(target);f.Downloads.Candidate=Cli;var manifest=new NativeUpdateManifest{schema_version=1,repository=NativeUpdater.Repository,component="native-init-cli",version=NativeData.Version,url="https://github.com/BerryFuwawa/codex-init-kit/releases/download/v"+NativeData.Version+"/CodexInitKit.Cli.exe",sha256=NativeCua.Hash(Cli)};var plan=new NativeUpdater(f.Downloads).Prepare(manifest,target,"2.3.0.0");Process parent=null;try{parent=Process.Start(new ProcessStartInfo(target,"sleep-short"){UseShellExecute=false,CreateNoWindow=true});var env=new Dictionary<string,string>{{"CODEX_HOME",f.P.Home},{"RTK_TELEMETRY_DISABLED","1"}};var completed=new NativeCommandRunner().Run(NativeUpdater.HelperPath(Cli),new[]{"--apply-update","--plan",plan.stage+".json","--parent-pid",parent.Id.ToString(),"--parent-start",parent.StartTime.ToUniversalTime().Ticks.ToString()},env,20000);Assert(!completed.TimedOut&&completed.ExitCode==0,"update helper: "+completed.Output+completed.Error);Assert(File.ReadAllBytes(target).SequenceEqual(File.ReadAllBytes(Cli)),"worker installed wrong bytes");var state=NativeData.Json.Deserialize<Dictionary<string,object>>(NativeData.Read(target+".update-result.json"));Assert(Convert.ToString(state["state"])=="complete","worker report");Assert(File.ReadAllBytes(Convert.ToString(state["backup"])).SequenceEqual(original),"worker backup bytes");Assert(!File.Exists(plan.stage)&&!File.Exists(plan.stage+".json"),"worker stage retained");}finally{if(parent!=null){if(!parent.HasExited)parent.Kill();parent.Dispose();}}});

  Test("real_native_child_runner_and_rtk_protocol_fixture",()=>{var f=new Fixture();string oldConfig=Environment.GetEnvironmentVariable("CODEX_NATIVE_TEST_RTK_CONFIG"),oldMode=Environment.GetEnvironmentVariable("CODEX_NATIVE_TEST_RTK_MODE");try{Environment.SetEnvironmentVariable("CODEX_NATIVE_TEST_RTK_CONFIG",f.P.RtkConfig);Environment.SetEnvironmentVariable("CODEX_NATIVE_TEST_RTK_MODE",null);f.S.Commands=new NativeCommandRunner();var r=f.Init();Assert(r.state=="complete",NativeData.Json.Serialize(r));Assert(NativeData.Read(f.P.RtkDoc).Contains("RTK 测试文档"),"real child doc missing");var before=f.Before[f.P.RtkConfig];NativeSession.Load(r.session,f.P).Restore(f.Registry);Assert(File.ReadAllBytes(f.P.RtkConfig).SequenceEqual(before),"RTK configuration not restored");}finally{Environment.SetEnvironmentVariable("CODEX_NATIVE_TEST_RTK_CONFIG",oldConfig);Environment.SetEnvironmentVariable("CODEX_NATIVE_TEST_RTK_MODE",oldMode);}});
  Test("real_command_timeout_keeps_output_and_ends_own_job",()=>{var f=new Fixture();string oldMode=Environment.GetEnvironmentVariable("CODEX_NATIVE_TEST_RTK_MODE");try{Environment.SetEnvironmentVariable("CODEX_NATIVE_TEST_RTK_MODE","timeout");var r=new NativeCommandRunner().Run(RtkFixture,new[]{"init","--global","--codex"},new Dictionary<string,string>{{"CODEX_HOME",f.P.Home},{"RTK_TELEMETRY_DISABLED","1"}},1500);Assert(r.TimedOut&&r.ExitCode!=0,"timeout status");Assert((r.Output??"").Contains("RTK 受控测试组件开始")&&(r.Error??"").Contains("标准错误"),"timeout lost emitted output");}finally{Environment.SetEnvironmentVariable("CODEX_NATIVE_TEST_RTK_MODE",oldMode);}});
  Test("real_process_identity_and_unrelated_process_preservation",()=>{var f=new Fixture();var owned=Path.Combine(f.P.LegacyCli,"codex.exe");Directory.CreateDirectory(f.P.LegacyCli);File.Copy(UpdateFixture,owned);var outside=Path.Combine(f.P.Documents,"unrelated.exe");File.Copy(UpdateFixture,outside);Process ours=null,unrelated=null;try{ours=Process.Start(new ProcessStartInfo(owned,"sleep"){UseShellExecute=false,CreateNoWindow=true});unrelated=Process.Start(new ProcessStartInfo(outside,"sleep"){UseShellExecute=false,CreateNoWindow=true});var provider=new WindowsNativeProcesses();var list=provider.List(f.P,f.Desktop.App);Assert(list.Any(x=>x.Id==ours.Id)&&!list.Any(x=>x.Id==unrelated.Id),"process path selection");var ticket=list.Single(x=>x.Id==ours.Id);var wrong=new ProcessIdentity{Id=ticket.Id,Started=ticket.Started+1,Path=ticket.Path,Owner=ticket.Owner,SessionId=ticket.SessionId,Name=ticket.Name};Throws(()=>provider.RequestExit(wrong,true),"进程已变化");Assert(!ours.HasExited&&!unrelated.HasExited,"identity mismatch killed process");provider.RequestExit(ticket,true);Assert(ours.WaitForExit(5000)&&!unrelated.HasExited,"owned close affected unrelated");provider.RequestExit(ticket,true);}finally{if(ours!=null){if(!ours.HasExited)ours.Kill();ours.Dispose();}if(unrelated!=null){if(!unrelated.HasExited)unrelated.Kill();unrelated.Dispose();}}});
 }
}

static partial class NativeTests {
 static string StreamedCode(){using(var s=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("NativeTest.CuaStreamed.js"))using(var r=new StreamReader(s,Encoding.UTF8))return r.ReadToEnd();}
 static string Asar(Dictionary<string,string> entries){var root=Path.Combine(Root,"asar-"+Guid.NewGuid().ToString("N"));var file=Path.Combine(root,"app","resources","app.asar");Directory.CreateDirectory(Path.GetDirectoryName(file));var meta=new Dictionary<string,object>();long offset=0;foreach(var item in entries){var bytes=Encoding.UTF8.GetBytes(item.Value);meta.Add(item.Key,new{size=bytes.Length,offset=offset.ToString()});offset+=bytes.Length;}var build=new Dictionary<string,object>{{"files",meta}};var vite=new Dictionary<string,object>{{"files",new Dictionary<string,object>{{"build",build}}}};var header=new Dictionary<string,object>{{"files",new Dictionary<string,object>{{".vite",vite}}}};var json=Encoding.UTF8.GetBytes(NativeData.Json.Serialize(header));using(var stream=new FileStream(NativePath.Io(file),FileMode.Create))using(var writer=new BinaryWriter(stream)){writer.Write((uint)4);writer.Write((uint)(json.Length+8));writer.Write((uint)(json.Length+4));writer.Write((uint)json.Length);writer.Write(json);foreach(var item in entries)writer.Write(Encoding.UTF8.GetBytes(item.Value));}return root;}
 static void DiscoveryTests(){
  Test("cua_streamed_algorithm_complete_data_flow",()=>{NativeCua.ValidateAlgorithm(StreamedCode(),"streamed");});
  Test("cua_streamed_incomplete_hash_rejected_even_with_direct_decoy",()=>{Throws(()=>NativeCua.ValidateAlgorithm(StreamedCode().Replace("subarray(0,e)","subarray(1,e)")+KnownAlgorithm,"streamed"),"哈希算法");});
  Test("cua_streamed_wrong_source_path_rejected",()=>{Throws(()=>NativeCua.ValidateAlgorithm(StreamedCode().Replace("filePath:r","filePath:t"),"streamed"),"哈希算法");});
  Test("cua_current_chunk_selected_by_unique_runtime_marker",()=>{var root=Asar(new Dictionary<string,string>{{"early-bootstrap-decoy.js","const unrelated=true;"},{"early-bootstrap-native.js",StreamedCode()}});string format;var code=NativeCua.ReadStartup(root,out format);Assert(format=="streamed"&&code==StreamedCode(),"streamed selection");NativeCua.ValidateAlgorithm(code,format);});
  Test("cua_legacy_asar_format_remains_supported",()=>{var root=Asar(new Dictionary<string,string>{{"application-network-startup-native.js",KnownAlgorithm}});string format;var code=NativeCua.ReadStartup(root,out format);Assert(format=="direct","legacy format");NativeCua.ValidateAlgorithm(code,format);});
  Test("cua_ambiguous_or_unknown_bundle_rejected",()=>{var root=Asar(new Dictionary<string,string>{{"early-bootstrap-a.js",StreamedCode()},{"early-bootstrap-b.js",StreamedCode()}});Throws(()=>{string format;NativeCua.ReadStartup(root,out format);},"唯一识别");root=Asar(new Dictionary<string,string>{{"other.js",KnownAlgorithm}});Throws(()=>{string format;NativeCua.ReadStartup(root,out format);},"唯一识别");});
 }
